ntory-options-content"><a class="button button-secondary button-compact" href="/aluno/inventario-item.php?id=<?=(int)$item['id']?>" data-student-editor-link>Editar item</a><form method="post" data-student-local-form data-local-refresh="inventory-stock inventory-history inventory-metrics" data-local-confirm="Arquivar este item? Ele sairá do estoque ativo, mas o histórico será preservado."><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-inventory'))?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><button class="button button-danger button-compact" type="submit">Arquivar</button></form></div></details></div></article><?php endforeach;?></div><?php endif;?></section>
